// Closure approach
function createCounter() {
  let count = 0;
  return { inc: () => ++count };
}
// Class approach
class Counter {
  constructor() { this.count = 0; }
  inc() { return ++this.count; }
}
const c1 = createCounter();
const c2 = new Counter();
console.log(c1.inc(), c2.inc());
